  "aty.cmp.method": "Core = rolling 10th percentile of the shadow diameter (40 mm window), not a global mean – loops only push the signal up, so the local lower envelope is the real core. Core CV = variability of that core along the yarn. Frequency / spacing = distance between detected loop peaks (prominence > 30 µm, min. distance 1 mm). Relative height = loop height as % of the local core. Bulk index = total loop area as % of the area of a loop-free yarn of the same core. Bin1/Bin2 = same height/length split as the Distribution tab, on these more accurate loops (so the % differ slightly). Core CV @1m / @20m = core unevenness at two length scales. Tail metrics (P95/P99/max) = how extreme the worst loops are.",
