  "aty.cmp.method": "芯线 = 阴影直径的滑动第 10 百分位（40 毫米窗口），而非全局均值 – 圈只会把信号往上推，因此局部下包络才是真正的芯线。芯线 CV = 该芯线沿纱线的波动。频率 / 间距 = 检测到的圈峰之间的距离（显著性 > 30 µm，最小距离 1 毫米）。相对高度 = 圈高度占局部芯线的百分比。蓬松指数 = 圈总面积占同芯线无圈纱线面积的百分比。Bin1/Bin2 = 与分布页相同的高度/长度划分，但基于更准确的圈（因此百分比略有不同）。芯线 CV @1m / @20m = 两种长度尺度下的芯线不匀。尾部指标（P95/P99/最大）= 最差圈的极端程度。",
